<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import MemoTimeInput from './MemoTimeInput.vue'
import { trapDialogTab } from './dialog'
import type { MemoMessage } from './domain'
const props=defineProps<{messages:MemoMessage[];scopeLabel?:string;ignored:boolean;loading:boolean;busy:boolean;error:string}>()
const emit=defineEmits<{close:[];toggle:[ignored:boolean];open:[message:MemoMessage];ignore:[message:MemoMessage];restore:[message:MemoMessage];complete:[message:MemoMessage];snooze:[message:MemoMessage,until:string]}>()
const snoozing=ref<MemoMessage>(),choice=ref(''),until=ref(''),customDay=ref(''),customClock=ref('09:00'),snoozeHeading=ref<HTMLElement>()
let snoozeTrigger:HTMLElement|null=null
const localParts=(date:Date)=>new Date(date.getTime()+8*3600000).toISOString().slice(0,16)
const tonight=computed(()=>localParts(new Date()).slice(0,10)+'T20:00:00+08:00')
const tonightPassed=computed(()=>Date.parse(tonight.value)<=Date.now())
function choose(value:string){choice.value=value;const now=new Date();if(['10','30','60'].includes(value))until.value=new Date(now.getTime()+Number(value)*60000).toISOString();else if(value==='tonight')until.value=tonight.value;else if(value==='tomorrow')until.value=localParts(new Date(now.getTime()+86400000)).slice(0,10)+'T09:00:00+08:00';else customTime()}
function customTime(){if(choice.value==='custom')until.value=customDay.value&&customClock.value?customDay.value+'T'+customClock.value+':00+08:00':''}
function openSnooze(message:MemoMessage){snoozeTrigger=document.activeElement as HTMLElement|null;snoozing.value=message;choice.value='';until.value='';customDay.value=localParts(new Date()).slice(0,10);void nextTick(()=>snoozeHeading.value?.focus())}
function closeSnooze(){if(props.busy)return;snoozing.value=undefined;void nextTick(()=>snoozeTrigger?.isConnected&&snoozeTrigger.focus())}
watch([()=>props.messages,()=>props.busy],([messages])=>{if(snoozing.value&&!messages.some(message=>message.id===snoozing.value!.id))closeSnooze()})
const page=ref(1),filter=ref('all')
const isReminder=(m:MemoMessage)=>['reminder','monthly_report','weekly_review'].includes(m.kind)
const visible=computed(()=>props.messages.filter(m=>!!m.ignored===props.ignored&&(filter.value==='all'||(filter.value==='reminder'?isReminder(m):!isReminder(m)))))
const pages=computed(()=>Math.max(1,Math.ceil(visible.value.length/5)))
watch([()=>props.ignored,filter],()=>{page.value=1})
watch(pages,total=>{page.value=Math.min(page.value,total)})
function label(message:MemoMessage){return({reminder:'备忘提醒',monthly_report:'月度复盘',weekly_review:'待补评价',memo_deletion_request:'备忘删除申请',plan_deletion_request:'愿望计划删除申请',expense_change_request:'财务更正申请',expense_category_change:'分类调整申请',family_invite:'家庭邀请'} as Record<string,string>)[message.kind]??'消息'}
</script>
<template>
<div class="modal-backdrop" @click.self="emit('close')" @keydown.esc.stop="snoozing?closeSnooze():emit('close')"><section class="form-card life-inbox" role="dialog" aria-modal="true" aria-label="消息提醒"><div class="form-title"><div><h2>消息提醒</h2><p class="form-note">{{ visible.length }} 条{{ ignored?'已忽略':'待处理' }} · {{ scopeLabel || '当前范围' }}</p></div><button type="button" class="icon-button" aria-label="关闭消息提醒" @click="emit('close')">×</button></div><div class="inbox-controls"><button type="button" class="text-button" :aria-pressed="ignored" :disabled="busy" @click="emit('toggle',!ignored)">{{ ignored?'返回待处理':'已忽略' }}</button><label>筛选<select v-model="filter" aria-label="筛选消息"><option value="all">全部</option><option value="request">申请与邀请</option><option value="reminder">提醒</option></select></label></div><p v-if="error" class="field-error" role="alert">{{ error }}</p><p v-if="loading" class="form-note" role="status">正在核对消息…</p><article v-for="message in visible.slice((page-1)*5,page*5)" :key="message.id" class="inbox-message"><button type="button" class="inbox-row" :disabled="busy" @click="emit('open',message)"><span><small>{{ label(message) }}</small><strong>{{ message.title }}</strong><small>{{ new Date(message.delivery_at??message.created_at).toLocaleString('zh-CN') }}</small></span><span aria-hidden="true">›</span></button><div class="inbox-actions"><template v-if="message.kind==='reminder'"><button type="button" class="memo-primary" :disabled="busy" @click="emit('complete',message)">{{ message.completion_scope==='occurrence'?'完成本次':'完成' }}</button><button type="button" class="memo-secondary" :disabled="busy" @click="openSnooze(message)">推后提醒</button></template><button v-if="ignored" type="button" class="text-button" :disabled="busy" :aria-label="`恢复消息：${message.title}`" @click="emit('restore',message)">恢复</button><button v-else type="button" class="text-button" :disabled="busy" :aria-label="`忽略消息：${message.title}`" @click="emit('ignore',message)">忽略</button></div></article><p v-if="!visible.length&&!loading" class="empty">{{ ignored?'没有已忽略的有效消息':'暂时没有待处理消息' }}</p><div v-if="pages>1" class="pagination"><button type="button" class="text-button" :disabled="page===1" @click="page--">上一页</button><span>第 {{ page }} / {{ pages }} 页</span><button type="button" class="text-button" :disabled="page===pages" @click="page++">下一页</button></div></section><div v-if="snoozing" class="memo-overlay" @click.self="closeSnooze" @keydown.esc.stop="closeSnooze"><form class="memo-modal memos-workspace" role="dialog" aria-modal="true" aria-labelledby="snooze-title" @keydown="trapDialogTab" @submit.prevent="until&&emit('snooze',snoozing,until)"><h3 id="snooze-title" ref="snoozeHeading" tabindex="-1">推后提醒</h3><p>{{ snoozing.title }}</p><div class="inbox-snooze-options"><button v-for="option in [{value:'10',label:'10分钟'},{value:'30',label:'30分钟'},{value:'60',label:'1小时'},{value:'tonight',label:'今晚'},{value:'tomorrow',label:'明天'},{value:'custom',label:'自选'}]" :key="option.value" type="button" class="memo-secondary" :aria-pressed="choice===option.value" :disabled="busy||option.value==='tonight'&&tonightPassed" @click="choose(option.value)">{{ option.label }}</button></div><p v-if="tonightPassed" class="memo-muted">今晚20:00已过</p><div v-if="choice==='custom'" class="memo-once-time memo-reminder-settings"><label class="memo-field"><span>提醒日期</span><input v-model="customDay" type="date" :disabled="busy" @change="customTime"></label><div class="memo-field"><span>提醒时间</span><MemoTimeInput v-model="customClock" :disabled="busy" @change="customTime"/></div></div><p v-if="until">将于 {{ new Date(until).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}) }} 再次提醒</p><p v-if="snoozing.source.scope==='shared'" class="memo-muted">这一次一起推后；只提醒原接收成员，后续重复时间不变。</p><p v-if="error" class="memo-error" role="alert">{{ error }}</p><div class="memo-form-actions"><button type="button" class="memo-text-button" :disabled="busy" @click="closeSnooze">取消</button><button type="submit" class="memo-primary" :disabled="busy||!until">{{ busy?'正在核对…':'确认推后' }}</button></div></form></div></div>
</template>

<style scoped>
.life-inbox{width:min(100%,520px);max-height:88dvh;overflow:auto}.inbox-controls{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:16px 0}.inbox-controls label{display:flex;align-items:center;gap:8px;font-size:13px;color:var(--sl-muted,#63766F)}.inbox-controls select{min-height:44px;max-width:155px;border:1px solid var(--sl-line,#DCE6E1);border-radius:10px;background:white;font-size:14px;padding:8px}.inbox-message{display:flex;flex-direction:column;align-items:stretch;gap:8px;border-bottom:1px solid var(--sl-line,#DCE6E1);padding:12px 0;min-width:0}.inbox-actions{display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center;padding-top:6px}.inbox-actions .text-button{margin-inline-start:auto;padding-inline:12px}.inbox-actions button{min-height:44px}.inbox-snooze-options{display:flex;gap:8px;flex-wrap:wrap}.inbox-snooze-options [aria-pressed=true]{border-color:var(--sl-brand);background:var(--sl-brand-soft)}.inbox-row{display:flex;align-items:center;gap:12px;border:0;background:none;flex:1;min-width:0;min-height:76px;padding:4px 0;text-align:left}.inbox-row>span:first-child{display:flex;flex-direction:column;gap:6px;min-width:0;flex:1}.inbox-row strong{font-size:15px;line-height:1.65;font-weight:550;overflow-wrap:anywhere}.inbox-row small{font-size:12px;color:var(--sl-muted,#63766F)}.inbox-row small:first-child{color:var(--sl-brand,#007F69);font-size:11px}.inbox-row>span:last-child{flex:none;color:var(--sl-muted,#63766F)}.inbox-message>.text-button{flex:none;min-width:44px;min-height:44px;font-size:13px}.pagination{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:16px;font-size:12px}
.inbox-actions .memo-primary{min-height:44px;padding:10px 15px;background:var(--sl-brand,#007f69);color:#fff;border:0;border-radius:11px;font-size:14px}.inbox-actions .memo-secondary{min-height:44px;padding:9px 12px;background:#fff;color:var(--sl-brand,#007f69);border:1px solid var(--sl-line,#dce6e1);border-radius:11px;font-size:13px}.memo-overlay{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;padding:20px 16px;background:#173b3055;backdrop-filter:blur(4px);overflow:auto}.memo-modal.memos-workspace{display:flex;flex-direction:column;gap:16px;width:100%;max-width:420px;min-height:0;max-height:calc(100dvh - 40px);overflow:auto;background:var(--sl-paper,#fff);border:1px solid var(--sl-line,#dce6e1);border-radius:18px;padding:20px;color:var(--sl-ink,#183a30)}.memo-modal p{overflow-wrap:anywhere}.memo-modal .memo-form-actions{position:static;flex:none;margin-top:4px;padding:12px 0 0;background:transparent}.memo-modal .memo-form-actions>.memo-primary{max-width:none}.inbox-actions button:focus-visible{outline:2px solid var(--sl-brand);outline-offset:3px}
</style>
